# Writes the hedra command files of the knight's arena: arena.txt (sand floor with painted rings and
# patches, a stone wall ring broken by four gates, gate pillars, a paved apron, a rocky underside),
# brazier.txt, flame.txt, banner.txt, boulder.txt, coin.txt, dust.txt.
# Run from models/env: /usr/bin/python3 make_env.py. Up Z, front -Y (hedra); colours exact Rust Gold 8.
# World (glTF, Y up) = (x, z, -y) of hedra; the gates sit at world angles 45, 135, 225, 315 degrees
# (x = r cos a, z = r sin a): front right, front left, back left, back right.
import math, random

HEX = {"gold": "f6cd26", "rust": "ac6b26", "brown": "563226", "dark": "331c17",
       "tan": "bb7f57", "mauve": "725956", "grey": "393939", "black": "202020"}
def col(n, emit=False):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")

R = 4.6            # sand floor radius
WR = 4.85          # wall centre line
GATES = [45, 135, 225, 315]
GATE_HALF = 11.0   # degrees of wall left out each side of a gate (an opening ~1.7 m wide)

def ring(r0, r1):
    return f"(pos.x*pos.x + pos.y*pos.y > {r0*r0:.4f} && pos.x*pos.x + pos.y*pos.y < {r1*r1:.4f})"
def circ(x, y, r):
    return f"((pos.x - ({x:.3f}))*(pos.x - ({x:.3f})) + (pos.y - ({y:.3f}))*(pos.y - ({y:.3f})) < {r*r:.4f})"

def hedra_ang(world_deg):            # world angle a (x = cos a, z = sin a) -> hedra angle (y = -z)
    return -world_deg

files = {}
rnd = random.Random(11)
patches = []
for i in range(12):
    a = rnd.uniform(0, 2 * math.pi); d = rnd.uniform(1.2, 3.9)
    patches.append(circ(d * math.cos(a), d * math.sin(a), rnd.uniform(0.2, 0.42)))
mark = " || ".join([ring(3.05, 3.3), ring(0.75, 0.95)] + patches)

wall = []
names = []
n = 36
for k in range(n):
    a = 360.0 * (k + 0.5) / n
    if any(abs(((a - g + 180) % 360) - 180) < GATE_HALF for g in GATES):
        continue
    ha = math.radians(hedra_ang(a))
    h = 0.75 + (0.18 if k % 2 == 0 else 0.0)            # crenellated: every other block taller
    L = 2 * WR * math.sin(math.pi / n) + 0.04
    x, y = WR * math.cos(ha), WR * math.sin(ha)
    nm = f"W{k}"
    wall += [f"add mesh cube --name {nm} --size 1 --location {x:.3f} {y:.3f} {h/2:.3f}",
             f"scale 0.45 {L:.3f} {h:.3f}", "apply --scale", f"set rotation 0 0 {math.degrees(ha):.2f}"]
    names.append(nm)
pil = []
for g in GATES:
    for s in (-1, 1):
        a = g + s * (GATE_HALF + 1.5)
        ha = math.radians(hedra_ang(a))
        x, y = WR * math.cos(ha), WR * math.sin(ha)
        nm = f"P{g}_{s+1}"
        pil += [f"add mesh cylinder --name {nm} --vertices 8 --radius 0.36 --depth 1.5 --location {x:.3f} {y:.3f} 0.75",
                f"add mesh cylinder --name {nm}c --vertices 8 --radius 0.44 --depth 0.14 --location {x:.3f} {y:.3f} 1.47"]
        names += [nm, f"{nm}c"]

files["arena"] = f"""# Arena: a 24-sided sand floor (top at z 0) fanned and subdivided so painted rings and darker
# patches are picked as faces; a paved apron ring (its top cut away under the sand) and a rocky
# underside below the rim; a crenellated
# stone wall broken by four gates, each flanked by two round pillars. Generated by make_env.py.
new
material new Sand {col('tan')} --no-slot
material new Mark {col('mauve')} --no-slot
material new Stone {col('mauve')} --no-slot
material new Pave {col('grey')} --no-slot
material new Rock {col('brown')} --no-slot
add mesh cylinder --name Floor --vertices 24 --radius {R} --depth 0.3 --location 0 0 -0.15
apply --location
material assign Sand
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
poke
select face where "normal.z > 0.5"
subdivide --cuts 9
select face where "normal.z > 0.5 && ({mark})"
material assign Mark
mode object
add mesh cylinder --name Apron --vertices 24 --radius 5.7 --depth 0.4 --location 0 0 -0.2
apply --location
material assign Pave
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
poke
select face where "normal.z > 0.9"
subdivide --cuts 3
select face where "normal.z > 0.9 && pos.x*pos.x + pos.y*pos.y < 4.4*4.4"
delete only-faces
mode object
add mesh cone --name Under --vertices 12 --radius1 5.6 --radius2 0.8 --depth 3.0 --location 0 0 -1.9 --rotation 180 0 0
apply --rotation
material assign Rock
mode edit
select face where "normal.z > 0.9"
delete only-faces
select vert where "pos.z < 1.2"
randomize --amount 0.25 --seed 5
mode object
""" + "\n".join(wall + pil) + f"""
select {' '.join(names)}
active {names[0]}
join
rename {names[0]} Wall
material assign Stone
select Floor Apron Under Wall
active Floor
join
rename Floor Arena
shade flat
export arena.glb
"""

files["brazier"] = f"""# Brazier: an iron bowl on a short stem (sits on a pillar top), origin at its foot. Up Z.
new
material new Iron {col('grey')} --no-slot
add mesh cone --name Bowl --vertices 8 --radius1 0.16 --radius2 0.32 --depth 0.24 --location 0 0 0.2
add mesh cylinder --name Stem --vertices 6 --radius 0.08 --depth 0.1 --location 0 0 0.05
select Bowl Stem
active Bowl
join
rename Bowl Brazier
material assign Iron
shade flat
export brazier.glb
"""

files["flame"] = f"""# Flame: three stacked faceted cones of fire, gold inside rust, origin at its foot (the game
# flickers it with stepped squash and stretch). Up Z.
new
material new Fire {col('rust', True)} --no-slot
material new Core {col('gold', True)} --no-slot
add mesh cone --name Outer --vertices 6 --radius1 0.26 --radius2 0 --depth 0.62 --location 0 0 0.31
material assign Fire
add mesh cone --name Inner --vertices 5 --radius1 0.15 --radius2 0 --depth 0.42 --location 0 -0.08 0.22 --rotation 0 0 20
material assign Core
select Outer Inner
active Outer
join
rename Outer Flame
shade flat
export flame.glb
"""

files["banner"] = f"""# Banner: a rust cloth with a gold band and a pointed tail hanging from a pole, flat (double sided
# in the bake), origin at the pole's centre. Up Z, faces -Y.
new
material new Cloth {col('rust')} --no-slot
material new Trim {col('gold')} --no-slot
material new Pole {col('dark')} --no-slot
add mesh cube --name Pole --size 1 --location 0 0 0
scale 0.9 0.08 0.08
apply --scale
material assign Pole
add mesh cube --name Cloth --size 1 --location 0 0 -0.55
scale 0.62 0.05 1.0
apply --scale
mode edit
select vert where "pos.z < -0.4 && abs(pos.x) < 0.01"
mode object
material assign Cloth
add mesh cone --name Tail --vertices 4 --radius1 0.44 --radius2 0 --depth 0.3 --location 0 0 -1.15 --rotation 0 180 45
apply --rotation
scale 1 0.11 1
apply --scale
material assign Cloth
add mesh cube --name Band --size 1 --location 0 -0.035 -0.35
scale 0.62 0.03 0.14
apply --scale
material assign Trim
select Pole Cloth Tail Band
active Cloth
join
rename Cloth Banner
shade flat
export banner.glb
"""

files["boulder"] = f"""# Boulder: a jittered, faceted ball 1 m across, origin at its centre (the game rolls it). Up Z.
new
material new Rock {col('brown')} --no-slot
material new Vein {col('rust')} --no-slot
add mesh ico-sphere --name Boulder --subdivisions 2 --radius 0.5 --location 0 0 0
material assign Rock
mode edit
select all
randomize --amount 0.07 --seed 9
select face where "pos.z > 0.3 && pos.x > 0.05"
material assign Vein
select face where "pos.z < -0.25 && pos.y > 0.1"
material assign Vein
mode object
shade flat
export boulder.glb
"""

files["coin"] = f"""# Coin: a fat gold octagonal coin standing upright (the game spins it), origin at its centre. Up Z.
new
material new Gold {col('gold')} --no-slot
material new Face {col('rust')} --no-slot
add mesh cylinder --name Coin --vertices 8 --radius 0.24 --depth 0.09 --location 0 0 0 --rotation 90 0 0
apply --rotation
material assign Gold
mode edit
select face where "abs(normal.y) > 0.9"
inset 0.08
material assign Face
mode object
shade flat
export coin.glb
"""

files["dust"] = f"""# Dust: a small faceted puff of sand, origin at its centre (pools of puffs: gate warnings, hits). Up Z.
new
material new Dust {col('tan')} --no-slot
add mesh ico-sphere --name Dust --subdivisions 1 --radius 0.16 --location 0 0 0
material assign Dust
shade flat
export dust.glb
"""

for k, v in files.items():
    open(f"{k}.txt", "w").write(v)
print("wrote", ", ".join(f"{k}.txt" for k in files))
